#include "rpi_pages.hpp"
#include "openoledui/widgets.hpp"
#include <cstdio>
namespace openoledui::rpi {namespace {void fmt(char*b,std::size_t n,float v,const char*s,int d=0){if(v<0)std::snprintf(b,n,"N/A");else if(d>0)std::snprintf(b,n,"%.*f%s",d,v,s);else std::snprintf(b,n,"%.0f%s",v,s);}void kv(Canvas&c,int y,const char*k,const char*v){c.text(3,y,k);c.text(48,y,v);}}
void OverviewPage::draw(Canvas&c,std::uint32_t){draw_header(c,"Pi 5",1,5);char b[24];fmt(b,sizeof(b),s_.temperature_c,"C",1);kv(c,17,"TEMP",b);fmt(b,sizeof(b),s_.cpu_percent,"%",0);kv(c,27,"CPU",b);fmt(b,sizeof(b),s_.memory_percent,"%",0);kv(c,37,"RAM",b);std::snprintf(b,sizeof(b),"%.2f",s_.load1);kv(c,47,"LOAD",b);}void NetworkPage::draw(Canvas&c,std::uint32_t){draw_header(c,"Network",2,5);draw_wifi_icon(c,107,18,3);kv(c,17,"IF",s_.interface.c_str());kv(c,27,"IP",s_.ipv4.c_str());char b[24];std::snprintf(b,sizeof(b),"%.1f KiB/s",s_.rx_kib_s);kv(c,37,"RX",b);std::snprintf(b,sizeof(b),"%.1f KiB/s",s_.tx_kib_s);kv(c,47,"TX",b);}void PowerPage::draw(Canvas&c,std::uint32_t now){draw_header(c,"Power",3,5);char b[24];fmt(b,sizeof(b),s_.supply_voltage_v,"V",2);kv(c,18,"EXT5V",b);fmt(b,sizeof(b),s_.core_current_a,"A",2);kv(c,29,"CORE I",b);std::snprintf(b,sizeof(b),"0x%05X",s_.throttled);kv(c,40,"FLAGS",b);c.text(3,51,s_.throttled?"CHECK POWER/THERM":"POWER OK");if(s_.throttled)draw_spinner(c,119,52,now);}void SystemPage::draw(Canvas&c,std::uint32_t){draw_header(c,"System",4,5);kv(c,16,"USER",s_.user.c_str());kv(c,25,"HOST",s_.hostname.c_str());char b[24];std::snprintf(b,sizeof(b),"%lluh",static_cast<unsigned long long>(s_.uptime_s/3600));kv(c,34,"UP",b);fmt(b,sizeof(b),s_.disk_percent,"%",0);kv(c,43,"DISK",b);c.progress_bar(3,53,122,6,s_.disk_percent<0?0:s_.disk_percent/100.0f);}void TerminalPage::draw(Canvas&c,std::uint32_t){draw_header(c,"Terminal",5,5);int y=15;for(const auto&line:f_.lines()){c.text(3,y,line.c_str());y+=7;}}
}
